// Import necessary modules and dependencies
import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Post,
  Query,
} from '@nestjs/common';
import { ApiOperation, ApiParam, ApiResponse, ApiTags } from '@nestjs/swagger';
// Import { OrderParameterDTO } from '@/modules/buffer/dtos/order-parameter.dto';

import { uniqBy } from 'lodash'; // Import lodash's uniqBy for simplicity
import { PickingOrder } from '../picking-order/picking-order.entity';
import { BufferCriteriaDTO } from './dtos/buffer-criteria.dto';
import { BufferFiltersSelectionsDTO } from './dtos/buffer-filters-selections.dto';
import { CreateBufferTableDto } from './dtos/buffer-table.dto';
import { FilterDTO } from './dtos/filter-request.dto';
import { KPICalculationDTO } from './dtos/kpi-calculation.dto';
import { ShoporderResponseDTO } from './dtos/shoporder-response.dto';
import { WkResponseDto } from './dtos/wk-response.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { Buffer } from '@/modules/buffer/buffer.entity';
import { BufferService } from '@/modules/buffer/buffer.service';
import { PickingOrderService } from '@/modules/picking-order/picking-order.service';
import { ProductionOrder } from '@/modules/production-order/production-order.entity';
import { ProductionOrderService } from '@/modules/production-order/production-order.service';

// Import { FilterSelectionsListDTO } from './dtos/filter-selections-list.dto';
// Define a type alias for the union type
type OrderItem = PickingOrder | Buffer | ProductionOrder;

// Controller for handling picking orders
@ApiTags('Buffer')
@Controller('buffer')
export class BufferController {
  private static readonly mapToShoporderResponse = (
    item: OrderItem,
  ): ShoporderResponseDTO => {
    const commonFields = {
      batch: BufferController.getBatch(item),
      batchTest: BufferController.getBatchTest(item),
      containerNumber: BufferController.getContainerNumber(item),
      createdProdSo: BufferController.getCreatedProdSo(item), // Populate as necessary
      customStatus: BufferController.getCustomStatus(item),
      customer: item.customer,
      customerDescription: '', // Populate as necessary
      destinationWc: BufferController.getDestinationWc(item),
      fromStorageBin: '', // Populate as necessary
      fromStorageLoc: item.sourceLocation || '',
      groupingSeq: 'groupingAgv' in item ? item.groupingAgv : '',
      kanbanType: BufferController.getKanbanType(item),
      material: BufferController.getMaterial(item),
      pickingTime: BufferController.getPickingTime(item),
      plcAssigned: BufferController.getPlcAssigned(item),
      productionTime: BufferController.getProductionTime(item),
      qtyDone: BufferController.getQtyDone(item) || '0',
      qtyScrapped: BufferController.getQtyScrapped(item) || '0',
      qtyToBuild: BufferController.getQtyToBuild(item),
      relatedOrder: BufferController.getRelatedOrder(item),
      sebango: 'sebango' in item ? item.sebango : '',
      shopOrder: BufferController.getShopOrder(item),
      toStorageBin: '', // Populate as necessary
      toStorageLoc: item.destinationLocation || '',
      tpaCode: BufferController.getTpaCode(item),
      workCenterDescription: BufferController.getWorkcenterDescription(item), // Populate as necessary
    };

    return commonFields as unknown as ShoporderResponseDTO;
  };

  private static getShopOrder(item: OrderItem): string {
    if ('shopOrder' in item && typeof item.shopOrder === 'string') {
      return item.shopOrder;
    }
    if ('orderId' in item && typeof item.orderId === 'string') {
      return item.orderId;
    }
    if ('pickingOrderId' in item && typeof item.pickingOrderId === 'string') {
      return item.pickingOrderId;
    }
    if (
      'productionOrderId' in item &&
      typeof item.productionOrderId === 'string'
    ) {
      return item.productionOrderId;
    }
    return '';
  }

  // Mapping Function
  private static isBuffer(item: OrderItem): item is Buffer {
    return (item as Buffer).neoIntegrationTime instanceof Date; // Specific to Buffer
  }

  private static getContainerNumber(item: OrderItem): string {
    if ('containerNumber' in item && typeof item.containerNumber === 'string') {
      return item.containerNumber;
    }
    return '';
  }

  private static getBatch(item: OrderItem): string {
    return typeof item.batch === 'string' ? item.batch : '';
  }

  private static getBatchTest(item: OrderItem): string {
    return typeof item.batchTest === 'string' ? item.batchTest : '';
  }

  private static getCustomStatus(item: OrderItem): string {
    if ('neoStatus' in item) {
      return item.neoStatus === null ? item.neoStatus : '';
    }
    if ('customStatus' in item) {
      return typeof item.customStatus === 'string' ? item.customStatus : '';
    }

    return '';
  }

  private static getQtyToBuild(item: OrderItem): string {
    if ('quantity' in item && typeof item.quantity === 'number') {
      return item.quantity.toString();
    }
    if ('qtyToBuild' in item && typeof item.qtyToBuild === 'number') {
      return item.qtyToBuild.toString();
    }
    return '';
  }

  private static getCreatedProdSo(item: OrderItem): number | string {
    if ('pikNumber' in item && typeof item.pikNumber === 'number') {
      return item.pikNumber;
    }
    return '';
  }

  private static getDestinationWc(item: OrderItem): string {
    if (
      !BufferController.isBuffer(item) &&
      typeof item.destinationWc === 'string'
    ) {
      return item.destinationWc;
    }

    return '';
  }

  private static getKanbanType(item: OrderItem): string {
    if (
      !BufferController.isBuffer(item) &&
      'kanbanType' in item &&
      typeof item.kanbanType === 'string'
    ) {
      return item.kanbanType;
    }
    return 'pickingOrderId' in item || 'orderId' in item ? 'WK' : '';
  }

  private static getMaterial(item: OrderItem): string {
    if (!BufferController.isBuffer(item) && typeof item.material === 'string') {
      return item.material;
    }
    if (typeof item.materialNumber === 'string') {
      return item.materialNumber;
    }
    return '';
  }

  private static getPickingTime(item: OrderItem): Date | string {
    const pickingTime =
      'startPickingDatetime' in item
        ? item.startPickingDatetime
        : item.plannedStartDate;
    return pickingTime instanceof Date ? pickingTime : '';
  }

  private static getPlcAssigned(item: OrderItem): unknown {
    return 'plcAssigned' in item ? item.plcAssigned : '';
  }

  private static getProductionTime(item: OrderItem): Date | string {
    // Check for 'startProductionDatetime' or fallback to 'scheduledCompDate'
    const productionTime =
      'startProductionDatetime' in item && item.startProductionDatetime
        ? item.startProductionDatetime
        : 'scheduledCompDate' in item && item.scheduledCompDate
          ? item.scheduledCompDate
          : '';

    return productionTime instanceof Date ? productionTime : '';
  }

  private static getQtyDone(item: OrderItem): number | string | true | object {
    if ('qtyDone' in item) {
      return item.qtyDone || '';
    }
    return '0';
  }

  private static getQtyScrapped(
    item: OrderItem,
  ): number | string | true | object {
    if ('qtyScrapped' in item) {
      return item.qtyScrapped || '';
    }
    return '0';
  }

  private static getRelatedOrder(item: OrderItem): string {
    return !BufferController.isBuffer(item) &&
      typeof item.relatedOrder === 'string'
      ? item.relatedOrder
      : '';
  }

  private static getTpaCode(item: OrderItem): string {
    return typeof item.tpaNumber === 'string' ? item.tpaNumber : '';
  }

  private static getWorkcenterDescription(item: OrderItem): string {
    if ('workcenter' in item && typeof item.workcenter === 'string') {
      return item.workcenter;
    }
    if ('productionLine' in item && typeof item.productionLine === 'string') {
      return item.productionLine;
    }
    return '';
  }

  private readonly logger = new AppLogger(BufferController.name);

  public constructor(
    private readonly bufferSer: BufferService,
    private readonly productionOrderSer: ProductionOrderService,
    private readonly pickingOrderSer: PickingOrderService,
  ) {}

  @Get('getShopOrderList')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Get ShorOrder List' })
  // @ApiBadRequestResponse({ type: [FilterDTO] })
  @ApiResponse({ status: HttpStatus.OK, type: [ShoporderResponseDTO] })
  @ApiResponse({ status: HttpStatus.BAD_REQUEST })
  public async getShopOrderList(
    @Query() filters: FilterDTO,
  ): Promise<Array<ShoporderResponseDTO> | undefined> {
    const isEmpty = (field: string | Array<string> | undefined): boolean => {
      return !field || (Array.isArray(field) && field.length === 0);
    };
    const transformBoolean = (
      field: boolean | number | undefined,
    ): boolean | undefined => {
      // Explicitly convert 1 and 0 to true and false
      if (field === 1 || field === true) return true;
      if (field === 0 || field === false) return false;
      return undefined;
    };
    const splitToArray = (
      field: string | Array<string> | undefined,
    ): Array<string> | undefined => {
      if (isEmpty(field)) {
        return undefined;
      }

      if (typeof field === 'string') {
        return field.split(';');
      }

      return field;
    };
    // Create a modified copy of the filters object
    const modifiedFilters = {
      ...filters,
      KanbanType: splitToArray(filters.KanbanType) ?? [],
      CustomStatus: splitToArray(filters.CustomStatus),
      DESTINATION_WC: splitToArray(filters.DESTINATION_WC),
      FromStorageBin: splitToArray(filters.FromStorageBin),
      FromStorageLoc: splitToArray(filters.FromStorageLoc),
      Material: splitToArray(filters.Material),
      ShopOrder: splitToArray(filters.ShopOrder),
      Status: splitToArray(filters.Status),
      TPA: splitToArray(filters.TPA),
      ToStorageBin: splitToArray(filters.ToStorageBin),
      ToStorageLoc: splitToArray(filters.ToStorageLoc),
      WorkCenter: splitToArray(filters.WorkCenter),
      Customer: filters.Customer?.trim() ?? undefined,
      EndPickingTime: filters.EndPickingTime?.trim() ?? undefined,
      EndProductionTime: filters.EndProductionTime?.trim() ?? undefined,
      StartPickingTime: filters.StartPickingTime?.trim() ?? undefined,
      StartProductionTime: filters.StartProductionTime?.trim() ?? undefined,
      AGVAssigned: transformBoolean(filters.AGVAssigned),
      OnlyPastPickingTime: transformBoolean(filters.OnlyPastPickingTime),
      PLCAssigned: transformBoolean(filters.PLCAssigned),
      WMS_ASSIGNED: transformBoolean(filters.WMS_ASSIGNED),
    };

    if (!modifiedFilters.KanbanType) return [];

    const isKanbanTypePIKorGHOSTorRW = ['PIK', 'GHOST', 'RW'].some((type) =>
      modifiedFilters.KanbanType?.includes(type),
    );
    const isKanbanTypeWK = modifiedFilters.KanbanType?.includes('WK');

    const fetchPromises = [
      ...(isKanbanTypeWK && modifiedFilters.CustomStatus?.includes('OPEN')
        ? [this.bufferSer.getFilteredBufferData(modifiedFilters)]
        : [Promise.resolve([])]),
      ...(isKanbanTypeWK
        ? [this.pickingOrderSer.getFilteredPickingData(modifiedFilters)]
        : []),
      ...(isKanbanTypePIKorGHOSTorRW
        ? [this.productionOrderSer.getFilteredProductionData(modifiedFilters)]
        : []),
    ];

    const [bufferData, pickingOrderData, productionOrderData] =
      await Promise.all(fetchPromises);

    const combinedData = [
      ...(Array.isArray(pickingOrderData) ? pickingOrderData : []),
      ...(Array.isArray(bufferData) ? bufferData : []),
      ...(Array.isArray(productionOrderData) ? productionOrderData : []),
    ];

    // Remove duplicates, keeping the first occurrence, which will be from pickingOrderData if a duplicate exists
    const uniqueData = uniqBy(combinedData, (item) =>
      BufferController.getShopOrder(item as OrderItem),
    );
    const mappedData = uniqueData.map(BufferController.mapToShoporderResponse);
    return mappedData;
  }

  @Post('insert')
  @HttpCode(HttpStatus.CREATED)
  @ApiOperation({ summary: 'Create a new Buffer Table entry' })
  @ApiResponse({ status: HttpStatus.CREATED, type: Buffer })
  @ApiResponse({ status: HttpStatus.BAD_REQUEST })
  public async createBufferTable(
    @Body() createBufferTableDto: CreateBufferTableDto,
  ): Promise<Buffer | { error: string }> {
    try {
      const result =
        await this.bufferSer.createBufferTable(createBufferTableDto);
      return result;
    } catch {
      return { error: 'Failed to create Buffer Table entry' };
    }
  }

  @Get('getWK/:plant/:offsetFrom/:offsetTo')
  @ApiOperation({
    summary: 'Retrieve  WK for a specified plant within a time range',
  })
  @ApiParam({
    description: 'The plant ID for which to retrieve wk',
    name: 'plant',
    required: true,
    schema: { type: 'integer' },
  })
  @ApiParam({
    description: 'Starting time offset (in minutes) from the current time',
    name: 'offsetFrom',
    required: true,
    schema: { type: 'integer' },
  })
  @ApiParam({
    description: 'Ending time offset (in minutes) from the current time',
    name: 'offsetTo',
    required: true,
    schema: { type: 'integer' },
  })
  @ApiResponse({
    description: 'Successfully retrieved wk',
    status: HttpStatus.OK,
    type: [Buffer],
  })
  @ApiResponse({
    description: 'Invalid parameters provided',
    status: HttpStatus.BAD_REQUEST,
  })
  @ApiResponse({
    description: 'No work items found for the specified parameters',
    status: HttpStatus.NOT_FOUND,
  })
  public async getWk(
    @Param('plant') plant: number,
    @Param('offsetFrom') offsetFrom: number,
    @Param('offsetTo') offsetTo: number,
  ): Promise<Array<WkResponseDto>> {
    return this.bufferSer.getWk(plant, offsetFrom, offsetTo);
  }

  @Delete('deleteExpiredOrders')
  @ApiOperation({
    description:
      'Deletes orders from the buffer table that are older than the defined retention time (10 days after launchDatetime).',
    summary: 'Delete expired orders from buffer table',
  })
  @ApiResponse({
    description: 'Successfully deleted expired orders from the buffer table.',
    schema: {
      example: {
        deletedCount: 5,
      },
    },
    status: HttpStatus.OK,
  })
  public async deleteExpiredOrders(): Promise<string> {
    try {
      const result = await this.bufferSer.deleteExpiredOrders();
      this.logger.log(
        `Expired orders deleted successfully ${result.deletedCount}`,
      );
      return `Expired orders deleted successfully ${result.deletedCount}`;
    } catch (error) {
      this.logger.error('Failed to delete expired orders');
      this.logger.error(error);
      return error.message;
    }
  }

  @Get('getKPICalculation/:plant')
  @ApiParam({
    description: 'The plant ID for which to retrieve wk',
    name: 'plant',
    required: true,
    schema: { type: 'integer' },
  })
  @ApiResponse({
    description: 'Successfully retrieved wk',
    status: HttpStatus.OK,
    type: [Buffer],
  })
  @ApiResponse({
    description: 'Invalid parameters provided',
    status: HttpStatus.BAD_REQUEST,
  })
  @ApiResponse({
    description: 'No work items found for the specified parameters',
    status: HttpStatus.NOT_FOUND,
  })
  public async getKPICalculation(
    @Param('plant') plant: number,
  ): Promise<KPICalculationDTO> {
    return this.bufferSer.getKPICalculation(plant);
  }

  @Get('getFiltersSelections/:plant')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Get filter selections' })
  @ApiResponse({ status: HttpStatus.BAD_REQUEST })
  public async getFiltersSelections(
    @Param('plant') plant: string,
  ): Promise<BufferFiltersSelectionsDTO> {
    const filters = {
      customerList: await this.bufferSer.getCustomerList(plant),
      destinationLocationList:
        await this.bufferSer.getDestinationLocationList(plant),
      materialList: await this.bufferSer.getMaterialList(plant),
      neoStatusList: await this.bufferSer.getNeoStatusList(plant),
      odList: await this.bufferSer.getOutboundDeliveryList(plant),
      sourceLocationList: await this.bufferSer.getSourceLocationList(plant),
      workcenterList: await this.bufferSer.getWorkCenterList(plant),
    };
    return filters;
  }

  // Make an API call to use  getBufferDataByCriteria
  @Get('getBufferDataByCriteria/:plant')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Get Buffer Data by Criteria' })
  @ApiResponse({ status: HttpStatus.OK, type: [Buffer] })
  @ApiResponse({ status: HttpStatus.BAD_REQUEST })
  public async getBufferDataByCriteria(
    @Param('plant') plant: string,
    @Query() criteria: BufferCriteriaDTO,
  ): Promise<Array<Buffer>> {
    return this.bufferSer.getBufferDataByCriteria(plant, criteria);
  }
}

