import { Module } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { TypeOrmModule } from '@nestjs/typeorm';

import { PickingOrderModule } from '../picking-order/picking-order.module';
import { ProductionOrderModule } from '../production-order/production-order.module';
import { BufferController } from '@/modules/buffer/buffer.controller';
import { Buffer } from '@/modules/buffer/buffer.entity';
import { BufferService } from '@/modules/buffer/buffer.service';

@Module({
  controllers: [BufferController],
  exports: [BufferService],
  imports: [
    TypeOrmModule.forFeature([Buffer]), // Import Buffer entity
    PickingOrderModule, // Import PickingOrderModule
    ProductionOrderModule, // Import ProductionOrderModule (which exports ProductionOrderService)
  ],
  providers: [
    BufferService, // Provide BufferService
    ConfigService, // Provide ConfigService
  ],
})
export class BufferModule {}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import {
  Brackets,
  In,
  LessThan,
  Repository,
  SelectQueryBuilder,
} from 'typeorm';
import { MaterialDtl } from '../material-dtl/material-dtl.entity';
import { BufferTableResponseDTO } from './dtos/buffer-table-resposne.dto';
import { IntegrationResponseMIIDTO } from './dtos/buffer-table-update.dto';
import { CreateBufferTableDto } from './dtos/buffer-table.dto';
import { FilterDTO } from './dtos/filter-request.dto';
import { KPICalculationDTO } from './dtos/kpi-calculation.dto';
import { WkResponseDto } from './dtos/wk-response.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { Buffer } from '@/modules/buffer/buffer.entity';

@Injectable()
export class BufferService {
  // Utility function to check for valid filter values
  public static isValidFilter(value: unknown): boolean {
    const isValid = value !== undefined && value !== null && value !== '';
    return isValid;
  }

  private static addFilters(
    queryBuilder: SelectQueryBuilder<Buffer>,
    filters: FilterDTO,
    fields: Array<{
      field: keyof FilterDTO;
      dbField: string;
      operator?: '=' | '<=' | '>='; // Optional operator
      isArray?: boolean; // Indicates if the filter is an array
    }>,
  ): void {
    for (const { field, dbField, operator = '=', isArray } of fields) {
      const filterValue = filters[field];
      if (BufferService.isValidFilter(filterValue)) {
        if (isArray && Array.isArray(filterValue)) {
          queryBuilder.andWhere(`${dbField} IN (:...${field})`, {
            [field]: filterValue,
          });
        } else if (!isArray) {
          queryBuilder.andWhere(`${dbField} ${operator} :${field}`, {
            [field]: filterValue,
          });
        }
      }
    }
  }

  private readonly retentionDays = 10;

  private readonly logger = new AppLogger(BufferService.name);

  public constructor(
    @InjectRepository(Buffer)
    private readonly bufferRepository: Repository<Buffer>,
  ) {}

  public async getFilteredBufferData(
    filters: FilterDTO,
  ): Promise<Array<Buffer>> {
    const queryBuilder: SelectQueryBuilder<Buffer> = this.bufferRepository
      .createQueryBuilder('buffer')
      .innerJoin(
        MaterialDtl,
        'material_dtl',
        'buffer.material_number = material_dtl.materialId AND buffer.plant = material_dtl.plant',
      )
      .where('buffer.plant = :plant', { plant: filters.Plant });
    // Optional material filtering

    // Selecting all fields in Buffer entity with aliases
    queryBuilder.select([
      'buffer.id AS id',
      'buffer.plant AS plant',
      'buffer.material_number AS material',
      'buffer.source_location AS sourceLocation',
      'buffer.destination_location AS destinationLocation',
      'buffer.quantity AS quantity',
      'buffer.customer AS customer',
      'buffer.action_type AS actionType',
      'buffer.start_picking_date_time AS startPickingDateTime',
      'buffer.end_picking_date_time AS endPickingDateTime',
      'buffer.delivery_number AS deliveryNumber',
      'buffer.production_line AS productionLine',
      'buffer.tpa_number AS tpaNumber',
      'buffer.end_preparation_date_time AS endPreparationTime',
      'buffer.truck_departure_date_time AS truckDepartureTime',
      'buffer.buffer_status AS bufferStatus',
      'buffer.neo_status AS neoStatus',
      'buffer.order_id AS orderId',
      'buffer.batch AS batch',
      'buffer.batch_test AS batchTest',
      'buffer.start_production_date_time AS startProductionDatetime',
    ]);

    // Selecting specific fields in MaterialDtl with aliases
    queryBuilder.addSelect([
      'material_dtl.grouping_agv AS groupingAgv',
      'material_dtl.sebango AS sebango',
    ]);

    // Subquery to get the latest buffer entry for each order_id
    const subQuery = this.bufferRepository
      .createQueryBuilder('subBuffer')
      .select('MAX(subBuffer.created_at)', 'maxBufferIntegrationTime')
      .addSelect('subBuffer.order_id')
      .groupBy('subBuffer.order_id');

    queryBuilder
      .innerJoin(
        `(${subQuery.getQuery()})`,
        'latest',
        'latest.order_id = buffer.order_id AND latest.maxBufferIntegrationTime = buffer.created_at',
      )
      .andWhere('buffer.neo_status IS NULL')
      .andWhere('buffer.bufferStatus IN (:...statusValues)', {
        statusValues: ['RECEIVED', 'IN_PROGRESS'],
      });

    // Abstract filter addition to reduce complexity
    BufferService.addFilters(queryBuilder, filters, [
      { dbField: 'buffer.customer', field: 'customer' as keyof FilterDTO },
      {
        dbField: 'buffer.start_picking_date_time',
        field: 'EndPickingTime',
        operator: '<=',
      },
      {
        dbField: 'buffer.start_production_date_time',
        field: 'EndProductionTime',
        operator: '<=',
      },
      { dbField: 'buffer.material_number', field: 'Material', isArray: true },
      { dbField: 'buffer.order_id', field: 'ShopOrder', isArray: true },
      { dbField: 'buffer.plant', field: 'Plant' },
      { dbField: 'buffer.production_line', field: 'WorkCenter', isArray: true },
      {
        dbField: 'buffer.source_location',
        field: 'FromStorageLoc',
        isArray: true,
      },
      {
        dbField: 'buffer.start_picking_date_time',
        field: 'StartPickingTime',
        operator: '>=',
      },
      {
        dbField: 'buffer.start_production_date_time',
        field: 'StartProductionTime',
        operator: '>=',
      },
      {
        dbField: 'buffer.destination_location',
        field: 'ToStorageLoc',
        isArray: true,
      },
      { dbField: 'buffer.tpa_number', field: 'TPA', isArray: true },
    ]);
    // Execute query and return result
    return queryBuilder.getRawMany();
  }

  /**
   * Adds filters to the query builder based on the provided configuration.
   * @param queryBuilder - The query builder instance to which filters will be added.
   * @param filters - The object containing filter criteria to apply to the query.
   * @param fields - The fields on which the filters are to be applied.
   */

  public async createBufferTable(
    createBufferTableDto: CreateBufferTableDto,
  ): Promise<Buffer> {
    const bufferTable = this.bufferRepository.create(createBufferTableDto);
    return this.bufferRepository.save(bufferTable);
  }

  /**
   * Retrieves list of buffer entries corresponding to the provided inputs
   * @param plant - The plant to which the WKs belong
   * @param orderIdList - The list of orderId values that should be filtered
   * @param bufferStatusList - The list of bufferStatus values that should be filtered
   */

  public async getBufferEntries(
    plant: number,
    orderIdList: Array<string>,
    bufferStatusList: Array<string>,
  ): Promise<Array<Buffer>> {
    return this.bufferRepository.find({
      where: {
        bufferStatus: In(bufferStatusList),
        orderId: In(orderIdList),
        plant,
      },
    });
  }

  /**
   * Updates entries from table buffer for the specified list of orderIds contained in updateBufferTableDto
   * @param plant - The plant to which the WKs belong
   * @param integrationResponseList - List of IntegrationResponseMIIDTO items
   * @returns A promise that resolves to an array of Buffer objects.
   */
  public async updateBufferWithMIIResult(
    plant: number,
    integrationResponseList: Array<IntegrationResponseMIIDTO>,
  ): Promise<Array<Buffer>> {
    // Create a lookup map from the MII reponse list
    const integrationResponseMap = new Map(
      integrationResponseList.map((integrationResponse) => [
        integrationResponse.orderId,
        integrationResponse,
      ]),
    );

    // Fetch the list of WKs
    const bufferEntries = await this.getBufferEntries(
      plant,
      integrationResponseList.map((object) => object.orderId),
      ['IN_PROGRESS'],
    );

    for (const buffer of bufferEntries) {
      // Get corresponding integrationResponse
      const integrationResponse = integrationResponseMap.get(buffer.orderId);

      if (integrationResponse) {
        buffer.bufferStatus = 'SUCCESS';
        buffer.neoStatus =
          integrationResponse.statusCode === 'SUCCESS'
            ? integrationResponse?.customStatus
            : 'ERROR';
        buffer.neoIntegrationTime = integrationResponse?.neoIntegrationTime;
        buffer.errorLog = integrationResponse?.statusMessage;
      }
    }

    // Return the array of updated buffers
    return this.bufferRepository.save(bufferEntries);
  }

  public async getWk(
    plant: number,
    offsetFrom: number,
    offsetTo: number,
  ): Promise<Array<WkResponseDto>> {
    const dateNow = new Date();
    const offsetFromDate = new Date(dateNow.getTime() + offsetFrom * 60_000);
    const offsetToDate = new Date(dateNow.getTime() + offsetTo * 60_000);

    const subQuery = this.bufferRepository
      .createQueryBuilder('subBuffer')
      .select('subBuffer.orderId', 'orderId')
      .addSelect('MAX(subBuffer.createdAt)', 'maxCreatedAt')
      .where('subBuffer.plant = :plant', { plant })
      .andWhere('subBuffer.bufferStatus = :bufferStatus', {
        bufferStatus: 'RECEIVED',
      })
      .groupBy('subBuffer.orderId');

    const result = await this.bufferRepository
      .createQueryBuilder('buffer')
      .innerJoin(
        `(${subQuery.getQuery()})`,
        'latestBuffer',
        'buffer.orderId = latestBuffer.orderId AND buffer.createdAt = latestBuffer.maxCreatedAt',
      )
      .where('buffer.plant = :plant', { plant })
      .andWhere('buffer.bufferStatus = :bufferStatus', {
        bufferStatus: 'RECEIVED',
      })
      .andWhere('buffer.neoStatus IS NULL')
      .andWhere(
        'buffer.launchDatetime BETWEEN :offsetFromDate AND :offsetToDate',
        {
          offsetFromDate,
          offsetToDate,
        },
      )
      .getMany();

    // Map the result to an array of WkResponseDto instances
    const responseDtos = result.map((item) => {
      const dto = new WkResponseDto();
      dto.actionType = item.actionType;
      dto.orderId = item.orderId;
      dto.materialNumber = item.materialNumber;
      dto.productionLine = item.productionLine;
      dto.tpaNumber = item.tpaNumber;
      dto.deliveryNumber = item.deliveryNumber;
      dto.startPickingDatetime = item.startPickingDatetime;
      dto.endPickingDatetime = item.endPickingDatetime;
      dto.quantity = item.quantity;
      dto.customer = item.customer;
      dto.productionLineUpstream = item.productionLineUpstream;
      dto.sourceLocation = item.sourceLocation;
      dto.destinationLocation = item.destinationLocation;
      dto.batch = item.batch;
      dto.batchTest = item.batchTest;
      dto.calendarType1 = item.calendarType1;
      dto.calendarType2 = item.calendarType2;
      dto.calendarType3 = item.calendarType3;
      dto.calendarType4 = item.calendarType4;
      dto.calendarType5 = item.calendarType5;
      dto.calendarType6 = item.calendarType6;
      dto.endPreparationDatetime = item.endPreparationDatetime;
      dto.truckDepartureDatetime = item.truckDepartureDatetime;
      dto.launchDatetime = item.launchDatetime;
      dto.startProductionDatetime = item.startProductionDatetime;
      dto.endProductionDatetime = item.endProductionDatetime;
      dto.upstreamMaterial = item.upstreamMaterial;
      return dto;
    });

    // Log if the response is empty
    if (responseDtos.length === 0) {
      this.logger.error(
        `No WK found for plant ${plant} in the specified time range from ${offsetFromDate.toISOString()} to ${offsetToDate.toISOString()}.`,
      );
    }
    if (responseDtos.length > 0) {
      const orderIds = responseDtos.map((dto) => dto.orderId);
      await this.updateBufferStatus(plant, orderIds, 'IN_PROGRESS', 'RECEIVED');
    }
    return responseDtos;
  }

  public async updateBufferStatus(
    plant: number,
    orderIds: Array<string>,
    newStatus: string,
    currentStatus = 'RECEIVED',
  ): Promise<void> {
    const updateResult = await this.bufferRepository
      .createQueryBuilder()
      .update(Buffer) // Assume Buffer is your entity
      .set({ bufferStatus: newStatus }) // Update to the new status
      .where('plant = :plant', { plant }) // Filter by plant
      .andWhere('orderId IN (:...orderIds)', { orderIds }) // Update specific order IDs
      .andWhere('bufferStatus = :currentStatus', { currentStatus }) // Ensure the current status is 'RECEIVED'
      .execute();

    // Log the result of the update
    if (updateResult.affected === 0) {
      this.logger.warn(
        `No records were updated for plant: ${plant}, with current status: ${currentStatus}.`,
      );
    } else {
      this.logger.log(
        `${updateResult.affected} records updated from ${currentStatus} to ${newStatus} for plant: ${plant}.`,
      );
    }
  }

  // Method to delete orders older than the retention period
  public async deleteExpiredOrders(): Promise<{ deletedCount: number }> {
    const retentionDate = new Date();
    retentionDate.setDate(retentionDate.getDate() - this.retentionDays);

    const deleteResult = await this.bufferRepository.delete({
      launchDatetime: LessThan(retentionDate),
    });

    return { deletedCount: deleteResult.affected ?? 0 };
  }

  public async getKPICalculation(plant: number): Promise<KPICalculationDTO> {
    const statusOrders = new KPICalculationDTO();
    const orders: Array<BufferTableResponseDTO> =
      await this.bufferRepository.find({
        select: ['orderId', 'bufferStatus', 'neoStatus'],
        where: {
          plant,
        },
      });
    if (orders.length > 0) {
      // Count the number of orders with red color
      statusOrders.failedorders = orders.filter(
        (order) => order.neoStatus === 'ERROR',
      ).length;
      // Count the number of orders with green color
      statusOrders.integratedOrders = orders.filter(
        (order) =>
          order.bufferStatus === 'SUCCESS' && order.neoStatus !== 'ERROR',
      ).length;
      // Count the number of orders with yellow color
      statusOrders.receivedOrders = orders.filter(
        (order) =>
          order.bufferStatus === 'RECEIVED' ||
          order.bufferStatus === 'IN_PROGRESS',
      ).length;
    }
    return statusOrders;
  }

  public async getWKOrdersByKPIName(
    plant: number,
    kpiName: string,
  ): Promise<Array<Buffer>> {
    const queryBuilder = this.bufferRepository
      .createQueryBuilder('buffer')
      .where('buffer.plant = :plant', { plant });

    switch (kpiName) {
      case 'failed': {
        queryBuilder.andWhere('buffer.neoStatus = :neoStatus', {
          neoStatus: 'ERROR',
        });
        break;
      }
      case 'integrated': {
        queryBuilder
          .andWhere('buffer.bufferStatus = :bufferStatus', {
            bufferStatus: 'SUCCESS',
          })
          .andWhere('buffer.neoStatus != :neoStatus', {
            neoStatus: 'ERROR',
          });
        break;
      }
      case 'received': {
        queryBuilder.andWhere(
          new Brackets((qb) => {
            qb.where('buffer.bufferStatus = :receivedStatus', {
              receivedStatus: 'RECEIVED',
            }).orWhere('buffer.bufferStatus = :inProgressStatus', {
              inProgressStatus: 'IN_PROGRESS',
            });
          }),
        );
        break;
      }
      default: {
        throw new Error(`Unknown KPI name: ${kpiName}`);
      }
    }

    const orders = await queryBuilder.getMany();
    return orders;
  }

