  public async getBufferDataByCriteria(
    plant: string,
    criteria: {
      neostatusList: Array<string>;
      customerList: Array<string>;
      materialList: Array<string>;
      sourceLocationList: Array<string>;
      destinationLocationList: Array<string>;
      outboundDeliveryList: Array<string>;
      workcenterList: Array<string>;
      startDate: Date;
      endDate: Date;
    },
  ): Promise<Array<Buffer>> {
    const queryBuilder = this.bufferRepository
      .createQueryBuilder('buffer')
      .where('buffer.plant = :plant', { plant });

    if (criteria.startDate) {
      queryBuilder.andWhere('buffer.createdAt >= :startDate', {
        startDate: criteria.startDate,
      });
    }

    if (criteria.endDate) {
      queryBuilder.andWhere('buffer.createdAt <= :endDate', {
        endDate: criteria.endDate,
      });
    }

    if (criteria.neostatusList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.neoStatus IN (:...neostatusList)', {
        neostatusList: criteria.neostatusList.filter(Boolean),
      });
    }

    if (criteria.customerList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.customer IN (:...customerList)', {
        customerList: criteria.customerList.filter(Boolean),
      });
    }

    if (criteria.materialList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.material_number IN (:...materialList)', {
        materialList: criteria.materialList.filter(Boolean),
      });
    }

    if (criteria.sourceLocationList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere(
        'buffer.sourceLocation IN (:...sourceLocationList)',
        {
          sourceLocationList: criteria.sourceLocationList.filter(Boolean),
        },
      );
    }

    if (criteria.destinationLocationList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere(
        'buffer.destinationLocation IN (:...destinationLocationList)',
        {
          destinationLocationList:
            criteria.destinationLocationList.filter(Boolean),
        },
      );
    }

    if (criteria.outboundDeliveryList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere(
        'buffer.deliveryNumber IN (:...outboundDeliveryList)',
        {
          outboundDeliveryList: criteria.outboundDeliveryList.filter(Boolean),
        },
      );
    }

    if (criteria.workcenterList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.productionLine IN (:...workcenterList)', {
        workcenterList: criteria.workcenterList.filter(Boolean),
      });
    }

    return queryBuilder.getMany();
  }
}

