/**
 * This controller handles endpoints related to picking orders.
 * It provides functionality to retrieve picking orders by ID for a specific plant.
 */

// Import necessary modules and dependencies
import {
  Controller,
  Get,
  InternalServerErrorException,
  NotFoundException,
  Param,
  Res,
} from '@nestjs/common';
import {
  ApiInternalServerErrorResponse,
  ApiNotFoundResponse,
  ApiOkResponse,
  ApiOperation,
  ApiParam,
  ApiTags,
} from '@nestjs/swagger';
import { Response } from 'express';
import { OrdersByDateResponse } from './dtos/orders-by-date-response';
import { PickingOrder } from './picking-order.entity';
import { OrderParameterDTO } from '@/modules/picking-order/dtos/order-parameter.dto';
import { OrdersByDateParameterDTO } from '@/modules/picking-order/dtos/orders-by-date-paramater.dto';
import PickingOrderResponseDTO from '@/modules/picking-order/dtos/picking-order-response.dto';
import { PickingOrderService } from '@/modules/picking-order/picking-order.service';
// Controller for handling picking orders
@ApiTags('Picking Order')
@Controller('picking-order')
export class PickingOrderController {
  public constructor(private readonly pickingOrderSer: PickingOrderService) {}

  @ApiOperation({
    description:
      'This endpoint lets you get a picking order of from a specific plant by id ',
    summary: 'Get picking order by plant and id',
  })
  @ApiOkResponse({
    description: 'The picking order ',
    type: PickingOrderResponseDTO,
  })
  @ApiNotFoundResponse({
    description: 'Picking Order Not Found.',
    status: 404,
  })
  @ApiInternalServerErrorResponse({
    description: 'Internal Server Error.',
    status: 500,
  })
  @Get('/order/:plant/:id')
  public async getPickingOrderById(
    @Param() query: OrderParameterDTO,
    @Res() response: Response,
  ): Promise<Response> {
    const { id, plant } = query;
    // Retrieve the picking order by ID for the specific plant
    try {
      const result = await this.pickingOrderSer.getOrderById(id, plant);
      return response.json(result);
    } catch (error) {
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve  picking order',
              error,
            );
      throw errorException;
    }
  }

  @ApiOperation({
    description:
      'This endpoint lets you get a picking order of from a specific plant by id ',
    summary: 'Get picking order by plant and id',
  })
  @ApiOkResponse({
    description: 'The picking order ',
    type: OrdersByDateResponse,
  })
  @ApiNotFoundResponse({
    description: ' Orders Not Found.',
    status: 404,
  })
  @ApiInternalServerErrorResponse({
    description: 'Internal Server Error.',
    status: 500,
  })
  @Get('/orders/:plant/:date')
  public async getPickingOrderByDate(
    @Param() query: OrdersByDateParameterDTO,
    @Res() response: Response,
  ): Promise<Response> {
    const { plant, date } = query;
    // Retrieve the picking order by ID for the specific plant
    try {
      const result = await this.pickingOrderSer.getOrdersByDate(plant, date);
      return response.json(result);
    } catch (error) {
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve orders',
              error,
            );
      throw errorException;
    }
  }

  @Get('without-wkHistories/:plant/:pickingOrderId')
  @ApiOperation({
    summary:
      'Get picking order by ID without without the relation reschedulerWkHistories',
  })
  @ApiParam({
    description: 'The plant ID',
    name: 'plant',
    required: true,
    type: Number,
  })
  @ApiParam({
    description: 'The picking order ID',
    name: 'pickingOrderId',
    required: true,
    type: String,
  })
  @ApiOkResponse({
    description: 'Picking order found without relation',
    type: PickingOrder,
  })
  @ApiNotFoundResponse({
    description: 'Picking order not found',
  })
  public async getOrderByIdWithoutWkHistories(
    @Param('pickingOrderId') pickingOrderId: string,
    @Param('plant') plant: number,
  ): Promise<PickingOrder> {
    return this.pickingOrderSer.getOrderByIdWithoutWkHistories(
      pickingOrderId,
      plant,
    );
  }
}

