import { PickingOrder } from '@/modules/picking-order/picking-order.entity';

@Injectable()
export class PickingOrderService {
  // Utility function to check for valid filter values
  public static isValidFilter(value: unknown): boolean {
    return value !== undefined && value !== null && value !== '';
  }

  public static isArrayFilter(value: unknown): boolean {
    return (
      Array.isArray(value) || (typeof value === 'object' && value !== null)
    );
  }

  private readonly logger = new AppLogger(PickingOrderService.name);

  public constructor(
    @InjectRepository(PickingOrder)
    private readonly pickingOrderRepo: Repository<PickingOrder>,
  ) {}

  public async getOrderById(
    pickingOrderId: string,
    plant: number,
  ): Promise<PickingOrder> {
    try {
      const order = await this.pickingOrderRepo.findOne({
        relations: ['reschedulerWkHistories'],
        where: {
          pickingOrderId,
          plant,
        },
      });

      if (!order) {
        throw new NotFoundException('Picking Order not Found');
      }

      return order;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve picking order by ID: ${error.message}`,
      );
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve picking order by id',
              error,
            );
      throw errorException;
    }
  }

  public async getOrdersByDate(
    plant: number,
    date: Date,
  ): Promise<Array<OrdersByDateResponse>> {
    try {
      const orders = await this.pickingOrderRepo.find({
        select: ['plant', 'pickingOrderId', 'status'],
        where: {
          plant,
          updatedAt: MoreThanOrEqual(date),
        },
      });

      if (!orders) {
        throw new NotFoundException('Picking Orders not Found');
      }

      return orders;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve picking orders by ID: ${error.message}`,
      );
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve picking orders by id',
              error,
            );
      throw errorException;
    }
  }

  public async getFilteredPickingData(
    filters: FilterDTO,
  ): Promise<Array<PickingOrder>> {
    const queryBuilder = this.pickingOrderRepo
      .createQueryBuilder('picking_order')
      .innerJoin(
        MaterialDtl,
        'material_dtl',
        'picking_order.material = material_dtl.materialId AND picking_order.plant = material_dtl.plant',
      )
      .where('picking_order.plant = :plant', { plant: filters.Plant });

    // Optional material filtering
    if (filters.Material && filters.Material.length > 0) {
      queryBuilder.andWhere('picking_order.material IN (:...material)', {
        materials: filters.Material,
      });
    }

    // Selecting all fields in PickingOrder entity with aliases
    queryBuilder.select([
      'picking_order.picking_order_id AS pickingOrderId',
      'picking_order.plant AS plant',
      'picking_order.material AS material',
      'picking_order.workcenter AS workcenter',
      'picking_order.status AS status',
      'picking_order.custom_status AS customStatus',
      'picking_order.pik_number AS pikNumber',
      'picking_order.source_location AS sourceLocation',
      'picking_order.destination_location AS destinationLocation',
      'picking_order.outbound AS outbound',
      'picking_order.tpa_number AS tpaNumber',
      'picking_order.related_label AS relatedLabel',
      'picking_order.container_number AS containerNumber',
      'picking_order.planned_comp_date AS plannedCompDate',
      'picking_order.scheduled_comp_date AS scheduledCompDate',
      'picking_order.created_date_time AS createdDateTime',
      'picking_order.planned_start_date AS plannedStartDate',
      'picking_order.customer AS customer',
      'picking_order.related_order AS relatedOrder',
      'picking_order.end_preparation_time AS endPreparationTime',
      'picking_order.truck_departure_time AS truckDepartureTime',
      'picking_order.rescheduled AS rescheduled',
      'picking_order.wms_assigned AS wmsAssigned',
      'picking_order.destination_wc AS destinationWc',
      'picking_order.scheduled_start_date AS scheduledStartDate',
      'picking_order.batch_test AS batchTest',
      'picking_order.batch AS batch',
      'picking_order.qty_scrapped AS qtyScrapped',
      'picking_order.qty_done AS qtyDone',
      'picking_order.qty_to_build AS qtyToBuild',
    ]);

    // Selecting specific fields in MaterialDtl with aliases
    queryBuilder.addSelect([
      'material_dtl.grouping_agv AS groupingAgv',
      'material_dtl.sebango AS sebango',
    ]);

    // Define the filtering logic
    const applyFilter = (
      field: string,
      value: unknown,
      operator = '=',
    ): void => {
      if (PickingOrderService.isValidFilter(value)) {
        // If the value is an array or object, handle it as an array
        if (
          PickingOrderService.isArrayFilter(value) &&
          operator !== 'BETWEEN'
        ) {
          // Use the 'IN' operator for array-like values
          queryBuilder.andWhere(`picking_order.${field} IN (:...${field})`, {
            [field]: value,
          });
        } else if (
          PickingOrderService.isArrayFilter(value) &&
          operator === 'BETWEEN' &&
          Array.isArray(value) &&
          value.length === 2
        ) {
          // Handle BETWEEN operator
          queryBuilder.andWhere(
            `picking_order.${field} BETWEEN :start AND :end`,
            {
              end: value[1],
              start: value[0],
            },
          );
        } else {
          // Standard filter
          queryBuilder.andWhere(
            `picking_order.${field} ${operator} :${field}`,
            {
              [field]: value,
            },
          );
        }
      }
    };

    // Apply filters using the helper function
    applyFilter('plant', Number(filters.Plant)); // Convert 'plant' to a number
    applyFilter('status', filters.Status, 'IN');
    applyFilter('customer', filters.Customer);
    applyFilter('agv_assigned', filters.AGVAssigned, 'IN');
    applyFilter('custom_status', filters.CustomStatus, 'IN');
    if (filters.StartPickingTime && filters.EndPickingTime) {
      applyFilter(
        'planned_start_date',
        [filters.StartPickingTime, filters.EndPickingTime],
        'BETWEEN',
      );
    } else if (filters.StartPickingTime) {
      applyFilter('planned_start_date', filters.StartPickingTime, '>=');
    } else if (filters.EndPickingTime) {
      applyFilter('planned_start_date', filters.EndPickingTime, '<=');
    }
    // Handle 'source_location' as an array or single value
    applyFilter('source_location', filters.FromStorageLoc, 'IN');

    applyFilter('material', filters.Material, 'IN');
    applyFilter('picking_order_id', filters.ShopOrder, 'IN');
    applyFilter('destination_location', filters.ToStorageLoc, 'IN');
    applyFilter('tpa_number', filters.TPA, 'IN');
    applyFilter('workcenter', filters.WorkCenter, 'IN');
    applyFilter('destination_wc', filters.DESTINATION_WC, 'IN');
    // Execute the query and return the result
    return queryBuilder.getRawMany();
  }

  public async getOrderByIdWithoutWkHistories(
    pickingOrderId: string,
    plant: number,
  ): Promise<PickingOrder> {
    try {
      // Fetching without the relation
      const order = await this.pickingOrderRepo.findOne({
        where: {
          pickingOrderId,
          plant,
        },
      });

      if (!order) {
        throw new NotFoundException('Picking Order not Found');
      }

      return order;
    } catch (error) {
      this.logger.error(`Failed to retrieve picking order : ${error.message}`);
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve picking order',
              error,
            );
      throw errorException;
    }
  }
}

