  BadRequestException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { PlantconfigDto } from './dtos/plant-config-parameter.dto'; // Adjust the path as necessary
import { PlantConfig } from './plant-config.entity';

@Injectable()
export class PlantconfigService {
  public constructor(
    @InjectRepository(PlantConfig)
    private readonly plantconfigRepository: Repository<PlantConfig>,
  ) {}

  public async findPlantConfigValuesByPlant(plant: number): Promise<{
    aggrTimeLvlBoard: number;
    offsetFrom: number;
    offsetTo: number;
  }> {
    const plantConfig = await this.plantconfigRepository.findOne({
      where: { plant },
    });

    if (!plantConfig) {
      throw new NotFoundException(
        `Plant configuration with plant ${plant} not found.`,
      );
    }

    return {
      aggrTimeLvlBoard: plantConfig.aggrTimeLvlBoard,
      offsetFrom: plantConfig.offsetFrom,
      offsetTo: plantConfig.offsetTo,
    };
  }

  // Update past_late_acceptance by plant
  public async updatePlantConfigValuesByPlant(
    aggrTimeLvlBoard: number,
    offsetFrom: number,
    offsetTo: number,
    plant: number,
  ): Promise<PlantConfig> {
    let plantConfig = await this.plantconfigRepository.findOne({
      where: { plant },
    });

    if (!plantConfig) {
      plantConfig = this.plantconfigRepository.create({
        aggrTimeLvlBoard,
        offsetFrom,
        offsetTo,
        plant,
      });

      return this.plantconfigRepository.save(plantConfig);
    }

    plantConfig.aggrTimeLvlBoard = aggrTimeLvlBoard;
    plantConfig.offsetFrom = offsetFrom;
    plantConfig.offsetTo = offsetTo;
    return this.plantconfigRepository.save(plantConfig);
  }

  // Add a new Plantconfig
  public async addPlantConfig(
    createPlantconfigDto: PlantconfigDto,
  ): Promise<PlantConfig> {
    const { aggrTimeLvlBoard, offsetFrom, offsetTo, plant } =
      createPlantconfigDto;

    const existingPlantConfig = await this.plantconfigRepository.findOne({
      where: { plant },
    });

    if (existingPlantConfig) {
      throw new BadRequestException(
        `Plant configuration with plant ${plant} already exists.`,
      );
    }

    const plantConfig = this.plantconfigRepository.create({
      aggrTimeLvlBoard,
      offsetFrom,
      offsetTo,
      plant,
    });

    return this.plantconfigRepository.save(plantConfig);
  }

  // Delete a Plantconfig by plant
  public async deletePlantConfigByPlant(plant: number): Promise<void> {
    const result = await this.plantconfigRepository.delete({ plant });

    if (result.affected === 0) {
      throw new NotFoundException(
        `Plant configuration with plant ${plant} not found.`,
      );
    }
  }

  public async getOffsetsByPlant(
    plant: number,
  ): Promise<{ offsetFrom: number; offsetTo: number }> {
    const plantConfig = await this.plantconfigRepository.findOne({
      where: { plant },
    });

    if (!plantConfig) {
      throw new NotFoundException(`No configuration found for plant ${plant}`);
    }

    return {
      offsetFrom: plantConfig.offsetFrom,
      offsetTo: plantConfig.offsetTo,
    };
  }
}

